\begin{tikzpicture}[line cap=round,line join=round,>=stealth,scale=1.0]
% concave mirror; shading on non-reflecting back (left)
\draw[thick] (-0.2,1.5) .. controls (0.85,0.45) and (0.85,-0.45) .. (-0.2,-1.5);
\foreach \y in {-1.3,-0.9,-0.5,-0.1,0.3,0.7,1.1} {\draw[thin] (-0.25,\y)--++(-0.28,0);}
\node[font=\small] at (-0.1,1.85) {concave mirror};
% parallel sunlight from the right
\draw[->,thick] (3.4,1.05)--(0.55,1.05);
\draw[->,thick] (3.4,0.0)--(0.75,0.0);
\draw[->,thick] (3.4,-1.05)--(0.55,-1.05);
% reflected rays meet at a bright spot on paper
\draw[->,thick] (0.55,1.05)--(2.05,0.08);
\draw[->,thick] (0.75,0.0)--(2.05,0.0);
\draw[->,thick] (0.55,-1.05)--(2.05,-0.08);
\draw[thick] (1.9,-0.5) rectangle (2.2,0.5);
\fill (2.05,0) circle (1.6pt);
\node[font=\footnotesize] at (2.9,0.55) {bright spot};
\node[font=\footnotesize] at (2.7,-0.75) {paper};
\end{tikzpicture}
